mapper.select:
SELECT count(*) FROM iam_tenant t WHERE t.deleted_at IS NULL
AND t.status = #{tenantStatus}
AND NOT EXISTS ( SELECT 1 FROM iam_role r JOIN iam_user_role ur ON ur.tenant_id = r.tenant_id AND ur.role_id = r.id AND ur.deleted_at IS NULL AND (ur.expires_at IS NULL OR ur.expires_at > now()) JOIN iam_user u ON u.tenant_id = ur.tenant_id AND u.id = ur.user_id AND u.status = 'ACTIVE' AND u.deleted_at IS NULL WHERE r.tenant_id = t.id AND r.role_code = 'tenant-admin' AND r.status = 'ACTIVE' AND r.deleted_at IS NULL )
